#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAX_NODE = 5500;
const int MAX_EDGE = 35500;
const int INF = 1000000000;

struct Arc {
    int next;
    int dest;
    int cap;
    int cost;
};

vector<Arc> graph(MAX_EDGE * 2 + 10);
vector<int> adj(MAX_NODE + 10);
int edge_cnt = 1;

void add_arc(int u, int v, int c, int w) {
    graph[++edge_cnt] = {adj[u], v, c, w};
    adj[u] = edge_cnt;
    graph[++edge_cnt] = {adj[v], u, 0, -w};
    adj[v] = edge_cnt;
}

int s, t, prev_node[MAX_NODE], last_arc[MAX_NODE], flow_arr[MAX_NODE], dist_arr[MAX_NODE];
bool in_q[MAX_NODE];

int spfa_run() {
    fill(dist_arr + 1, dist_arr + t + 1, INF);
    fill(flow_arr + 1, flow_arr + t + 1, 0);
    flow_arr[s] = INF;
    dist_arr[s] = 0;
    queue<int> q;
    q.push(s);
    in_q[s] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        in_q[u] = false;

        for (int e = adj[u]; e; e = graph[e].next) {
            int v = graph[e].dest;
            if (graph[e].cap && dist_arr[v] > dist_arr[u] + graph[e].cost) {
                dist_arr[v] = dist_arr[u] + graph[e].cost;
                flow_arr[v] = min(flow_arr[u], graph[e].cap);
                last_arc[v] = e;
                prev_node[v] = u;
                if (!in_q[v]) {
                    in_q[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return flow_arr[t];
}

int n, m, k, base_cost, unit_cost;
int loc_record[105][105];
int edge_count_rec[105][105];
struct Journey { int src, dst; } edges_in[105];

#define to_node(r,c) ((r)*(n)+(c))

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m >> k >> base_cost >> unit_cost;
    s = to_node(n+k, n) + 1;
    t = s + 2;

    add_arc(to_node(0,1), t, INF, 0);

    for (int i = 1, port; i <= k; ++i) {
        cin >> port;
        add_arc(s, to_node(0,port), 1, 0);
    }

    for (int i = 1; i <= m; ++i) {
        cin >> edges_in[i*2].src >> edges_in[i*2].dst;
        edges_in[i*2-1] = {edges_in[i*2].dst, edges_in[i*2].src};
    }
    m <<= 1;

    for (int day = 1; day <= n + k; ++day) {
        for (int i = 1; i <= n; ++i)
            add_arc(to_node(day-1, i), to_node(day, i), INF, 0);
        for (int i = 1; i <= m; ++i) {
            add_arc(to_node(day-1, edges_in[i].src), to_node(day, edges_in[i].dst), 1, unit_cost);
            loc_record[day][i] = edge_cnt;
            edge_count_rec[day][i] = 1;
        }
        add_arc(to_node(day, 1), t, INF, day * base_cost);
    }

    int augment, total = 0;
    while (augment = spfa_run()) {
        int cur = t;
        while (cur != s) {
            int u = prev_node[cur];
            graph[last_arc[cur]].cap -= augment;
            graph[last_arc[cur]^1].cap += augment;
            cur = u;
        }
        total += dist_arr[t] * augment;

        for (int day = 1; day <= n+n; ++day)
            for (int i = 1; i <= m; ++i)
                if (graph[loc_record[day][i]].cap) {
                    edge_count_rec[day][i]++;
                    add_arc(to_node(day-1, edges_in[i].src), to_node(day, edges_in[i].dst), 1,
                            unit_cost * (edge_count_rec[day][i]*2 - 1));
                    loc_record[day][i] = edge_cnt;
                }
    }

    cout << total << '\n';
    return 0;
}
